<?php if($order['audit_status']==='approved'&&$order['lifecycle_status']==='active'&&empty($order['selected_quote_id'])): ?><section id="order-share" class="admin-card admin-mt-3"><header class="admin-card__header"><div><h2 class="admin-card__title">普通订单分享</h2><span class="admin-text-muted">打开者按接单大厅权限查看，不会自动成为师傅</span></div></header><div class="admin-card__body"><form class="admin-form-grid" method="post" action="<?= e(admin_url('orders.invite',['id'=>$order['id']])) ?>"><?= csrf()->input() ?><input type="hidden" name="share_type" value="ordinary"><button class="admin-btn admin-btn--primary" type="submit" data-confirm="确认生成普通订单分享及对应小程序码？"><i class="ri-share-forward-line"></i> 生成普通订单分享</button></form></div></section><?php endif; ?>
<?php if($order['audit_status']==='approved'&&$order['lifecycle_status']==='active'&&!empty($order['selected_quote_id'])&&$order['selected_quote_type']==='platform'&&$order['payment_status']==='paid'&&empty($order['assigned_worker_id'])): ?><section id="order-share" class="admin-card admin-mt-3"><header class="admin-card__header"><div><h2 class="admin-card__title">邀请师傅分享</h2><span class="admin-text-muted">受邀用户登录后无需认证即可成为本单师傅</span></div></header><div class="admin-grid admin-grid--2 admin-card__body">
    <form class="admin-form-grid" method="post" action="<?= e(admin_url('orders.invite',['id'=>$order['id']])) ?>"><?= csrf()->input() ?><div class="admin-alert admin-alert--warning admin-field--full"><div class="admin-alert__body"><strong>服务费必须提前说明</strong>按成交价比例计算，每单最低 <?= e(money($order['commission_min_cents'])) ?>；预约费在应收服务费中抵扣。重新生成会撤销此前未领取口令。</div></div><div class="admin-field"><label class="admin-label">本单服务费比例（%）</label><input class="admin-control" type="number" name="commission_rate" min="0" max="100" step="0.01" value="<?= e(number_format($order['commission_rate_bp']/100,2,'.','')) ?>" required></div><div class="admin-field"><label class="admin-label">邀请有效天数</label><input class="admin-control" type="number" name="valid_days" min="1" max="30" value="7" required></div><div class="admin-field admin-field--full"><label class="admin-label">调整/分享原因</label><input class="admin-control" name="reason" maxlength="500" value="管理员分享订单给受邀师傅"></div><button class="admin-btn admin-btn--primary" type="submit" data-confirm="确认生成新的单次邀请口令？旧的未领取口令将立即失效。" data-confirm-type="primary">生成邀请口令</button></form>
    <div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>创建/到期</th><th>费率</th><th>状态</th><th>领取人</th><th>操作</th></tr></thead><tbody><?php foreach($invites as $invite): $inviteMeta=status_meta($invite['status']); ?><tr><td><strong><?= e(local_datetime($invite['created_at'])) ?></strong><small class="admin-table__secondary"><?= e(local_datetime($invite['expires_at'])) ?></small></td><td><?= e(number_format($invite['rate_bp']/100,2)) ?>%<small class="admin-table__secondary">最低 <?= e(money($invite['min_fee_cents'])) ?></small></td><td><span class="admin-badge admin-badge--<?= e($inviteMeta[1]) ?>"><?= e($inviteMeta[0]) ?></span><small class="admin-table__secondary"><?= (int)$invite['claim_count'] ?>/<?= (int)$invite['max_claims'] ?></small></td><td><?= e($invite['claimed_worker_name']?:'—') ?></td><td><?php if($invite['status']==='active'): ?><form method="post" action="<?= e(admin_url('orders.invite.revoke',['id'=>$order['id']])) ?>"><?= csrf()->input() ?><input type="hidden" name="invite_id" value="<?= (int)$invite['id'] ?>"><button class="admin-btn admin-btn--sm admin-btn--danger" type="submit" data-confirm="确认撤销该邀请？">撤销</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?><?php if(!$invites): ?><tr><td colspan="5"><div class="admin-empty">尚未生成邀请</div></td></tr><?php endif; ?></tbody></table></div>
</div></section><?php endif; ?>
<?php endif; ?>
<div class="admin-grid admin-grid--2 admin-mt-3">
    <section class="admin-card"><header class="admin-card__header"><h2 class="admin-card__title">报价记录</h2></header><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>来源</th><th>报价人</th><th>金额</th><th>状态</th><th>报价时间</th></tr></thead><tbody><?php foreach($quotes as $quote): $meta=status_meta($quote['status']);$isSelected=(int)$quote['id']===(int)$order['selected_quote_id']; ?><tr><td><?= $quote['source']==='platform'?'平台报价':'师傅报价' ?></td><td><?= e($quote['worker_name']?:$quote['admin_name']?:'平台') ?></td><td class="admin-money"><?= e(money($quote['total_amount_cents'])) ?></td><td><span class="admin-badge admin-badge--<?= $isSelected?'success':e($meta[1]) ?>"><?= $isSelected?'用户已选择':e($meta[0]) ?></span></td><td><?= e(local_datetime($quote['created_at'])) ?><small class="admin-table__secondary">不设有效期</small></td></tr><?php endforeach; ?><?php if(!$quotes): ?><tr><td colspan="5"><div class="admin-empty">暂无报价</div></td></tr><?php endif; ?></tbody></table></div></section>
